      <UnifiedSearch />
      <div class="suggestions"><span>试试搜索</span><button v-for="word in suggestions" :key="word" @click="searchWord(word)">{{ word }}</button></div>
    </section>
    <section class="metrics"><article><strong>{{ paperCount===null?'—':compact(paperCount) }}</strong><span>可检索论文</span></article><article><strong>{{ ACADEMIC_CONFERENCE_COUNT }}</strong><span>学术会议</span></article><article><strong>{{ yearRange }}</strong><span>年份覆盖</span></article><article><strong>{{ categories.length||'—' }}</strong><span>研究方向</span></article></section>
    <div class="section-heading"><div><p class="page-eyebrow">RESOURCE PORTALS</p><h2>按资源类型继续探索</h2></div><span>每个入口只展示对应类别的结果</span></div>
    <section class="resource-portals"><button v-for="item in portals" :key="item.type" @click="router.push(item.path)"><span>{{ item.index }}</span><div><strong>{{ item.label }}</strong><small>{{ item.description }}</small></div><el-icon><ArrowRight /></el-icon></button></section>
    <section class="overview-grid">
      <div class="surface-card popular"><div class="card-head"><div><p class="page-eyebrow">DATA OVERVIEW</p><h2>高收录量会议</h2></div><button @click="router.push('/knowledge/conferences')">查看全部</button></div><div v-if="loading" class="status">正在读取会议统计数据…</div><button v-for="(v,i) in topVenues" :key="v.conference" class="venue-row" @click="openVenue(v.conference)"><span>{{ String(i+1).padStart(2,'0') }}</span><strong>{{ v.conference }}</strong><em>{{ compact(v.count) }} 篇</em><small>{{ v.minYear }}—{{ v.maxYear }}</small><el-icon><ArrowRight /></el-icon></button></div>
