    </section>
  </div>
</template>
<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'; import {useRouter} from 'vue-router'; import {ArrowRight} from '@element-plus/icons-vue'; import UnifiedSearch from '@/components/UnifiedSearch.vue'; import {ACADEMIC_CONFERENCE_COUNT} from '@/config/knowledgeStats'; import {fetchCategories,fetchPaperVenues} from '@/services/api'; import {fetchRetrievalHealth} from '@/services/retrieval'; import type {Category} from '@/types/conference'; import type {PaperVenue} from '@/types/paper'
const router=useRouter(),venues=ref<PaperVenue[]>([]),categories=ref<Category[]>([]),paperCount=ref<number|null>(null),loading=ref(true); const suggestions=['graph neural networks','大语言模型','知识图谱补全','多模态学习']; const portals=[{type:'paper',index:'01',label:'论文',description:'题名、摘要、作者与会议',path:'/resources/papers'},{type:'patent',index:'02',label:'专利',description:'发明成果与技术方案',path:'/resources/patents'},{type:'scholar',index:'03',label:'学者',description:'研究方向与合作线索',path:'/resources/scholars'},{type:'project',index:'04',label:'项目',description:'科研任务与技术方向',path:'/resources/projects'},{type:'fund',index:'05',label:'基金',description:'资助主题与研究计划',path:'/resources/funds'}]; const topVenues=computed(()=>[...venues.value].sort((a,b)=>b.count-a.count).slice(0,5)); const yearRange=computed(()=>venues.value.length?`${Math.min(...venues.value.map(v=>v.minYear))}—${Math.max(...venues.value.map(v=>v.maxYear))}`:'—'); const compact=(n:number)=>n>=10000?`${(n/10000).toFixed(1)}万`:n.toLocaleString('zh-CN'); const openVenue=(venue:string)=>router.push({name:'conference-detail',params:{venue}}); const searchWord=(q:string)=>router.push({path:'/knowledge',query:{q}})
onMounted(async()=>{const[h,v,c]=await Promise.allSettled([fetchRetrievalHealth(),fetchPaperVenues(),fetchCategories()]);if(h.status==='fulfilled'&&Number.isFinite(h.value.lexical?.paper_count))paperCount.value=h.value.lexical!.paper_count!;if(v.status==='fulfilled')venues.value=v.value;if(c.status==='fulfilled')categories.value=c.value;loading.value=false})
</script>
