d-template-columns:auto 1fr auto;align-items:center;gap:12px;padding:20px;text-align:left;background:#fff;border:1px solid var(--sz-line);border-radius:14px;cursor:pointer;transition:.18s}.resource-portals button:hover{transform:translateY(-2px);border-color:#b7c5e6;box-shadow:var(--sz-shadow)}.resource-portals button>span{color:#c1cada;font-size:20px;font-weight:800}.resource-portals strong,.resource-portals small{display:block}.resource-portals strong{color:var(--sz-navy);font-size:17px}.resource-portals small{margin-top:4px;color:var(--sz-text-muted);font-size:11px}.resource-portals .el-icon{color:var(--sz-primary)}.overview-grid{display:grid;grid-template-columns:1.4fr .8fr;gap:20px}.popular,.workflow{padding:26px}.card-head button{color:var(--sz-primary);background:none;border:0;cursor:pointer}.venue-row{width:100%;display:grid;grid-template-columns:42px 1fr 90px 140px 20px;align-items:center;gap:10px;padding:15px 0;color:var(--sz-text-muted);background:none;border:0;border-bottom:1px solid var(--sz-line);text-align:left;cursor:pointer}.venue-row strong{color:var(--sz-text)}.venue-row em{color:var(--sz-text-secondary);font-style:normal}.status{padding:34px 0;color:var(--sz-text-muted)}.workflow ol{margin:22px 0 0;padding:0;list-style:none}.workflow li{display:flex;gap:14px;padding-bottom:24px}.workflow li>b{width:33px;height:33px;display:grid;place-items:center;color:var(--sz-primary);background:var(--sz-primary-soft);border-radius:9px}.workflow p{margin:5px 0;color:var(--sz-text-muted);font-size:13px}@media(max-width:1100px){.resource-portals{grid-template-columns:repeat(2,1fr)}.overview-grid{grid-template-columns:1fr}}@media(max-width:650px){.search-hero{padding:34px 18px}.metrics,.resource-portals{grid-template-columns:1fr}.metrics article{border-right:0;border-bottom:1px solid var(--sz-line)}.venue-row{grid-template-columns:34px 1fr 70px}.venue-row small,.venue-row .el-icon{display:none}}
